import { existsSync, readFileSync, statSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { z } from "zod";
import type { ToolDefinition } from "./definition";

/**
 * Search and read the project wiki: `docs/index.json`, generated by
 * `npm run wiki:index` from every page's tags and summary, and the pages it
 * lists. Works when the plugin runs from a clone of camera-director; reads
 * those files only, never the studio, never pays. A page is opened only if the
 * index lists its path, so no other file can be read through it.
 */
const TAG = /^[a-z0-9][a-z0-9-]{0,31}$/;
/** An index larger than this is refused rather than parsed. */
export const MAX_INDEX_BYTES = 1024 * 1024;
/** A page longer than this is returned cut, with `truncated: true`. */
export const MAX_PAGE_CHARS = 48 * 1024;
const REPO = "https://github.com/koshimazaki/Genobi/blob/main/docs/";

export interface WikiPage {
  title: string;
  path: string;
  tags: string[];
  summary: string;
}
export interface WikiIndex {
  tags: Record<string, { meaning: string; pages: string[] }>;
  pages: WikiPage[];
}

/** `docs/` beside the bundled server (plugins/genobi/server) or `mcp/`. */
export function docsRoot(
  from = path.dirname(fileURLToPath(import.meta.url)),
): string {
  const candidates = [
    path.join(from, "..", "..", "..", "docs"),
    path.join(from, "..", "docs"),
  ];
  return (
    candidates.find((dir) => existsSync(path.join(dir, "index.json"))) ??
    candidates[0]
  );
}

export function readWikiIndex(root: string): WikiIndex {
  const file = path.join(root, "index.json");
  if (!existsSync(file) || statSync(file).size > MAX_INDEX_BYTES)
    throw new Error(
      `The wiki index is not here; it ships with a clone of camera-director (run npm run wiki:index). Read the wiki at ${REPO}README.md.`,
    );
  const data = JSON.parse(readFileSync(file, "utf8")) as Partial<WikiIndex>;
  if (!Array.isArray(data.pages) || typeof data.tags !== "object")
    throw new Error("docs/index.json is not a wiki index.");
  return { tags: data.tags ?? {}, pages: data.pages };
}

export interface WikiQuery {
  tag?: string;
  text?: string;
}

/** Pages matching every filter given: a tag, words in the title, summary or path. */
export function searchWiki(index: WikiIndex, query: WikiQuery) {
  if (query.tag !== undefined && !(query.tag in index.tags))
    throw new Error(
      `Unknown tag. Use one of: ${Object.keys(index.tags).join(", ")}.`,
    );
  const words = (query.text ?? "").toLowerCase().split(/\s+/).filter(Boolean);
  return index.pages
    .filter((page) => {
      if (query.tag && !page.tags.includes(query.tag)) return false;
      const haystack =
        `${page.title} ${page.summary} ${page.path}`.toLowerCase();
      return words.every((word) => haystack.includes(word));
    })
    .map(({ title, path: file, tags, summary }) => ({
      title,
      path: file,
      tags,
      summary,
    }));
}

/** One page's Markdown, by the path the index lists. */
export function readWikiPage(root: string, index: WikiIndex, page: string) {
  const listed = index.pages.find((entry) => entry.path === page);
  if (!listed)
    throw new Error(
      "No such page in the wiki index. Search first and pass a path it returns.",
    );
  const text = readFileSync(path.join(root, listed.path), "utf8");
  const truncated = text.length > MAX_PAGE_CHARS;
  return {
    title: listed.title,
    path: listed.path,
    url: `${REPO}${listed.path}`,
    text: truncated ? text.slice(0, MAX_PAGE_CHARS) : text,
    truncated,
  };
}

export function docsTools(root = docsRoot()): ToolDefinition[] {
  return [
    {
      name: "genobi_docs",
      title: "Genobi wiki",
      description:
        "Search and read the project wiki (docs/). With no arguments, list the tags and how many pages carry each. With tag or text, return matching pages: title, path, tags and summary. With page (a path a search returned), return that page's Markdown. Reads the wiki files of a camera-director clone only; never pays.",
      inputSchema: {
        tag: z
          .string()
          .regex(TAG)
          .optional()
          .describe("A wiki tag, for example storyboard or camera"),
        text: z
          .string()
          .min(1)
          .max(100)
          .optional()
          .describe("Words that must all appear in the title, summary or path"),
        page: z
          .string()
          .min(1)
          .max(200)
          .optional()
          .describe("A page path from a search result, such as scrolls.md"),
      },
      tags: ["wiki", "agents", "mcp"],
      docs: ["docs/README.md", "docs/tags.md"],
      annotations: { readOnlyHint: true, idempotentHint: true },
      async run(_api, args) {
        const index = readWikiIndex(root);
        const query = args as WikiQuery & { page?: string };
        if (query.page !== undefined)
          return readWikiPage(root, index, query.page);
        if (!query.tag && !query.text)
          return {
            tags: Object.fromEntries(
              Object.entries(index.tags).map(([tag, { meaning, pages }]) => [
                tag,
                { meaning, pages: pages.length },
              ]),
            ),
          };
        return { pages: searchWiki(index, query) };
      },
    },
  ];
}
